from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient

app = FastAPI()

@app.post("/upload")
async def upload(name: str = Form(...), file: UploadFile = File(...)):
    return {"name": name, "filename": file.filename}

client = TestClient(app)

def test_form_before_file():
    # This should work, but according to the issue, it might fail with 422
    # if File is declared after Form.
    files = {"file": ("test.txt", b"hello world")}
    data = {"name": "test name"}
    response = client.post("/upload", data=data, files=files)
    print(f"Response status code: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_form_before_file()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()

