from fastapi.testclient import TestClient
from typing import List

app = FastAPI()

@app.post("/upload")
async def upload(name: str = Form(...), files: List[UploadFile] = File(...)):
    return {"name": name, "filenames": [f.filename for f in files]}

client = TestClient(app)

def test_form_before_multiple_files():
    files = [
        ("files", ("test1.txt", b"hello world")),
        ("files", ("test2.txt", b"foo bar")),
    ]
    data = {"name": "test name"}
    response = client.post("/upload", data=data, files=files)
    print(f"Response status code: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_form_before_multiple_files()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()

